const items = $input.all();
const details = items.map(item => ({
  id: item.json.id,
  email: item.json.email || undefined,
  name: item.json.name || undefined
}));
return [{
  json: {
    payload: { details: details },
    contacts_input: items.map(i => i.json)
  }
}];

const data = $input.first().json;
const records = data.matches || data.people || [];
const inputContacts = $('Construire payload Apollo').first().json.contacts_input || [];

const results = [];
for (let i = 0; i < records.length; i++) {
  const m = records[i] || {};
  const original = inputContacts[i] || {};
  results.push({
    json: {
      contact_id: original.id,
      name: original.name,
      email: original.email,
      apollo_id: m.id || '',
      linkedin_url: m.linkedin_url || '',
      twitter_url: m.twitter_url || '',
      github_url: m.github_url || '',
      facebook_url: m.facebook_url || '',
      city: m.city || '',
      state: m.state || '',
      country: m.country || '',
      seniority: m.seniority || '',
      headline: m.headline || '',
      photo_url: m.photo_url || '',
      status: m.linkedin_url ? 'success' : 'no_linkedin'
    }
  });
}
return results;
